mapper.select:
SELECT 
FROM document d
LEFT JOIN knowledge_base kb ON kb.id = d.knowledge_base_id
LEFT JOIN user u ON u.id = d.user_id
WHERE d.deleted = 0

  AND d.knowledge_base_id = #{knowledgeBaseId}


  AND d.user_id = #{userId}


  AND d.file_name LIKE CONCAT('%', #{keyword}, '%')


  AND (d.parse_status = #{status}
       OR d.chunk_status = #{status}
       OR d.vector_status = #{status})
